def _getObjectIdByName(objectName, objectType):
    expr = "type=" + objectType + "&expr=[name=='" + objectName + "']&f=objectId"
    results = dm.ExecuteSimManagerQuery(expr)
    objectId = ""
    if results and len(results) == 1:
        objectId = results[0].get("Id")
    return objectId

