    btnText = guitk.BCButtonText(b)
    if guitk.BCButtonGroupId(btnGroup, b) == -1:
        print("\nButton {} is NOT a member of the ButtonGroup".format(btnText))
    print("{} state set to {}".format(btnText, state))
