        guitk.BCButtonGroupRemove(btnGroup, selectedBtn)
        print(
            "\nRemoved Button with Id = "
            + str(guitk.BCButtonGroupGetSelectedId(btnGroup))
        )
    else:
        print("\nNo selected ButtonGroup Button")
    return 0


