            selectedItem, col, guitk.constants.BCNormalMode
        )
        guitk.BCListViewItemColumnResetForegroundColor(
            selectedItem, col, guitk.constants.BCNormalMode
        )
    else:
        print("Select an Item first.")
    return 0


